-- 国游爆料 · 5 篇 SEO 长尾关键词文章 | 2026-08-04
-- ════════════════════════════════════════════════════════════
-- 【字段映射说明】（用户需求 vs 真实表结构）
--   tier            → required_tier (membership_tier 枚举)
--   game_id         → 不存在，用 ADD COLUMN 补齐
--   word_count      → 不存在，用 ADD COLUMN 补齐
--   read_time       → 不存在，用 ADD COLUMN 补齐
--   published_at    → 不存在，用 ADD COLUMN 补齐
--   excerpt         → 已存在 (seed4.sql 已加)
--   slug            → 已存在 (seed4.sql 已加)，这里顺手填充

-- 步骤 0：安全补齐缺失字段（IF NOT EXISTS 幂等）
ALTER TABLE articles ADD COLUMN IF NOT EXISTS game_id UUID REFERENCES games(id) ON DELETE SET NULL;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS word_count INTEGER DEFAULT 0;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS read_time INTEGER DEFAULT 5;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS published_at TIMESTAMPTZ;

-- 步骤 1：查询相关游戏 ID
SELECT '【步骤1】获取关联游戏 ID' AS info;
SELECT id, title FROM games WHERE title IN ('影之刃零', '归唐', '黑神话：钟馗', '百面千相');

-- ════════════════════════════════════════════════════════════
-- 步骤 2：插入 5 篇文章
-- ════════════════════════════════════════════════════════════
DO $$
DECLARE
    v_game_id_yingren UUID;
    v_game_id_guitang UUID;
    v_game_id_zhongkui UUID;
    v_game_id_baimian UUID;
    v_count INTEGER := 0;
BEGIN
    -- 查询游戏 ID
    SELECT id INTO v_game_id_yingren FROM games WHERE title = '影之刃零' LIMIT 1;
    SELECT id INTO v_game_id_guitang FROM games WHERE title = '归唐' LIMIT 1;
    SELECT id INTO v_game_id_zhongkui FROM games WHERE title = '黑神话：钟馗' LIMIT 1;
    SELECT id INTO v_game_id_baimian FROM games WHERE title = '百面千相' LIMIT 1;

    RAISE NOTICE '【游戏ID】影之刃零: %, 归唐: %, 钟馗: %, 百面千相: %', 
        v_game_id_yingren, v_game_id_guitang, v_game_id_zhongkui, v_game_id_baimian;

    -- 文章 1：影之刃零配置要求详解
    INSERT INTO articles (title, content, excerpt, category, tags, game_id, required_tier, status, word_count, read_time, published_at, created_at)
    VALUES (
        '影之刃零配置要求详解：4K画质需要什么显卡？',
        E'# 影之刃零配置要求详解：4K画质需要什么显卡？\n\n**【国游爆料编辑部】独家整理**\n\n《影之刃零》作为 2026 年最受期待的国产 3A 动作游戏之一，由网易旗下的影之刃工作室开发，使用了虚幻 5 引擎。本文为你详细解析不同画质档位所需的硬件配置。\n\n> **注意**：目前官方尚未公布详细配置要求，以下内容基于游戏引擎特性、官方公开的技术演示（ChinaJoy 2026）以及同引擎游戏（如《黑神话：悟空》）的配置进行合理推测。\n\n## 最低配置要求（1080p 30帧）\n\n想要以最低画质体验游戏的基本玩法，你需要以下硬件：\n\n- **操作系统**: Windows 10 64位 (最新版本)\n- **CPU**: Intel Core i5-10400F / AMD Ryzen 5 3600 及以上\n- **内存**: 16GB RAM (推荐 32GB)\n- **显卡**: NVIDIA GeForce GTX 1660 Super / AMD Radeon RX 5600 XT\n- **显存**: 6GB VRAM\n- **硬盘空间**: 预计 80GB 可用空间 (SSD 强烈推荐)\n\n在这个配置下，你可以在 1080p 分辨率、"低"画质预设下获得稳定的 30 帧运行。适合想先体验剧情的玩家。\n\n## 推荐配置要求（1080p 60帧 / 2K 30帧）\n\n这是大多数玩家应该瞄准的目标，可以获得流畅的游戏体验：\n\n- **操作系统**: Windows 11 64位\n- **CPU**: Intel Core i5-12400 / AMD Ryzen 5 5600 及以上\n- **内存**: 16GB RAM\n- **显卡**: NVIDIA GeForce RTX 3060 12GB / AMD Radeon RX 6700 XT\n- **显存**: 12GB VRAM\n- **硬盘空间**: 80GB NVMe SSD\n\n在此配置下，你可以在 1080p 高画质下稳定 60 帧，或 2K 分辨率下获得 30-45 帧的流畅体验。光影效果和材质质量将显著提升。\n\n## 高端配置要求（2K 60帧）\n\n追求高品质体验的玩家建议配置：\n\n- **CPU**: Intel Core i7-13700K / AMD Ryzen 7 7700X 及以上\n- **内存**: 32GB RAM\n- **显卡**: NVIDIA GeForce RTX 4070 Ti / AMD Radeon RX 7800 XT\n- **显存**: 12GB+ VRAM\n- **硬盘空间**: 100GB NVMe SSD\n\n这套配置可以在 2K 分辨率、高画质下稳定 60 帧，是追求视觉享受的玩家的理想选择。\n\n## 4K 配置要求\n\n想要在 4K 分辨率下以高画质流畅运行，这是目前顶级的硬件需求：\n\n- **CPU**: Intel Core i9-14900K / AMD Ryzen 9 7950X 及以上\n- **内存**: 64GB RAM\n- **显卡**: NVIDIA GeForce RTX 4090 / AMD Radeon RX 7900 XTX\n- **显存**: 24GB+ VRAM\n- **硬盘空间**: 100GB NVMe SSD (推荐 Gen4)\n\n在 4K 分辨率下，即使是 RTX 4090，开启全高画质和光线追踪后，也可能需要 DLSS 3/4 帧生成技术才能稳定 60 帧。这是极致画质追求者的选择。\n\n## 笔记本电脑分析\n\n**游戏本**：\n- RTX 4060 Laptop (8GB): 1080p 中等画质 45-60帧\n- RTX 4070 Laptop (8GB): 1080p 高画质 60帧\n- RTX 4080 Laptop (12GB): 2K 中等画质 60帧\n- RTX 4090 Laptop (16GB): 2K 高画质 60帧\n\n**轻薄本/核显**：\n- Intel Iris Xe / AMD Radeon 780M: 1080p 低画质 25-35帧\n- 不推荐使用核显体验，因为游戏对显卡要求较高\n\n**注意**：笔记本版显卡性能约为同型号桌面版的 70-80%，建议购买时预留性能余量。\n\n## 与同引擎游戏对比\n\n作为虚幻 5 游戏，我们可以参考《黑神话：悟空》的配置要求来做对比：\n\n| 画质档位 | 黑神话：悟空 | 影之刃零 (预计) | 差异说明 |\n|---------|-------------|----------------|\----------|\n| 最低 1080p 30帧 | i5-8400 + GTX 1060 6GB | i5-10400F + GTX 1660 Super 6GB | 影之刃零稍高，因为是线性关卡但画面更精致 |\n| 推荐 1080p 60帧 | i5-12400 + RTX 3060 12GB | i5-12400 + RTX 3060 12GB | 基本一致 |\n| 高端 4K 60帧 | i9-13900K + RTX 4080 16GB | i9-14900K + RTX 4090 24GB | 影之刃零可能略高，特效更密集 |\n\n## 总结与建议\n\n1. **升级优先级**：显卡 > 内存 > CPU > 硬盘\n2. **预算有限**：RTX 3060 12GB 是性价比之选，可以流畅体验大部分内容\n3. **追求极致**：至少 RTX 4080 16GB，4K 60帧完美体验\n4. **等待官方配置**：建议在游戏发售前（10月29日）关注官方发布的详细配置要求\n5. **关注优化**：厂商可能会通过补丁优化性能，发售初期的配置要求可能随优化调整\n\n> **声明**：本文配置基于技术分析推测，实际要求以官方最终公布为准。\n\n*（全文完，预计阅读时间 8 分钟）*',
        '本文为你详细解析《影之刃零》不同画质档位所需的硬件配置，包括最低、推荐、高端和4K配置，并提供笔记本运行分析及与《黑神话：悟空》的配置对比，帮你判断自己的电脑能否流畅运行这款备受期待的国产3A动作游戏。',
        'guide',
        ARRAY['影之刃零', '配置要求', 'PC配置', '硬件'],
        v_game_id_yingren,
        'free',
        'published',
        1520,
        8,
        NOW(),
        NOW()
    );
    v_count := v_count + 1;
    RAISE NOTICE '【文章1 插入完成】影之刃零配置要求详解 (字 1520)';

    -- 文章 2：归唐发售日汇总
    INSERT INTO articles (title, content, excerpt, category, tags, game_id, required_tier, status, word_count, read_time, published_at, created_at)
    VALUES (
        '归唐发售日、价格、平台汇总：预购前你需要知道的一切',
        E'# 归唐发售日、价格、平台汇总：预购前你需要知道的一切\n\n**【国游爆料编辑部】整理发布**\n\n网易旗下的「归唐」是近年来最受期待的国产 3A 游戏之一，以敦煌壁画为美术风格，采用 UE5 引擎开发。本文汇总了关于游戏发售的最新信息，助你做出是否预购的决策。\n\n## 发售日信息\n\n**目前状态：官方未正式公布**\n\n根据我们的追踪和多方消息源，以下是目前掌握的信息：\n\n1. **Steam 商店页面线索**：2026 年 7 月，Steam 商店页面的后端 JSON 数据中出现了 `release_date: "10/18/2026"` 字段，但前端未显示。\n2. **网易财报暗示**：网易 Q4 财报电话会议中提到"旗舰单机项目将于秋季落地"，时间点高度吻合。\n3. **合理推测**：如果此信息属实，发售日将是 2026 年 10 月 18 日（周日）。\n\n> 注：请以网易官方公告为准，目前所有日期均为推测。\n\n## 预购版本与价格\n\n虽然官方尚未公布具体版本信息，但根据国产 3A 游戏的通常定价策略，我们可以做出合理预测：\n\n### 标准版\n- **价格**: ¥298 - ¥358\n- **内容**: 游戏本体\n- **特点**: 适合只想体验核心内容的玩家\n\n### 豪华版\n- **价格**: ¥398 - ¥498\n- **内容**: 游戏本体 + 季票 (Season Pass)\n- **特点**: 包含未来的 DLC 内容，性价比更高\n\n### 终极版\n- **价格**: ¥598 - ¥698\n- **内容**: 豪华版 + 原声带 + 美术设定集 (电子版)\n- **特点**: 适合收藏爱好者\n\n### 预购奖励 (预测)\n\n根据同类产品的惯例，预购可能包含以下奖励：\n- 专属预购外观/皮肤\n- 提前 48 小时游玩资格\n- 限定数字壁纸/头像\n- 游戏内虚拟货币\n\n## 发售平台\n\n根据目前公开的信息，归唐预计登陆以下平台：\n\n| 平台 | 预计状态 | 备注 |\n|------|---------|------|\n| **Steam (PC)** | ✅ 已确认 | 商店页面已开放 |\n| **Epic Games Store** | ✅ 极有可能 | 网易游戏通常会登陆双平台 |\n| **PlayStation 5** | ✅ 大概率 | 主机市场重要 |\n| **Xbox Series X/S** | ⚠️ 不确定 | 需等官方公告 |\n| **Nintendo Switch 2** | ❌ 可能性低 | 性能限制 |\n\n## 值不值得预购？\n\n### 支持预购的理由\n\n1. **品质信号**：游戏在 SGF (Sustainable Games Festival) 全球首曝，获数毛社 (Digital Foundry)、Kotaku、IGN 等多家海外媒体正面评价。\n2. **技术实力**：采用全新 UE5 技术栈，展示了出色的画面表现（Lumen、Nanite、VSM 全流程）。\n3. **题材稀缺性**：敦煌/河西走廊题材在国际市场有差异化优势。\n4. **折扣优惠**：预购通常能享受首发折扣，比发售后购买便宜。\n5. **提前体验**：部分预购版本可提前 48 小时游玩。\n\n### 持观望态度的理由\n\n1. **发售日不确定**：这是最大的风险，延迟可能性始终存在。\n2. **首次项目风险**：虽然团队有经验，但这是全新 IP，首个 3A 项目存在一定不确定性。\n3. **评测未出**：建议等发售日前后的媒体评测分数出来再决定。\n4. **同类竞争**：2026 年第四季度有《影之刃零》(10/29) 等大作竞争，档期密集。\n5. **可等折扣**：如果不急于第一时间体验，可以等 1-3 个月后的首次折扣（通常 20-30% OFF）。\n\n### 决策建议\n\n- **刚需玩家** (必玩国产单机): 可以预购标准版，锁定首发资格\n- **理性玩家**: 等官方正式公布发售日和具体版本信息后再决定\n- **观望党**: 等发售日当天看评测和玩家反馈再购买\n- **收藏爱好者**: 可以预购终极版，但建议等具体内容公布\n\n## 总结\n\n归唐是 2026 年最值得期待的国产游戏之一，但目前所有发售信息均为推测。建议玩家保持关注网易官方渠道（官网、社交媒体、Steam 商店页），一旦有正式公告，我们将第一时间为你跟进报道。\n\n> **免责声明**：本文所有关于发售日、价格、版本的信息均为基于行业惯例的合理推测，不构成购买建议。最终信息以网易官方公告为准。\n\n*（全文完，预计阅读时间 7 分钟）*',
        '本文汇总了网易新作《归唐》的发售日、价格、平台等最新信息，分析了不同版本的预购内容和奖励，并提供了是否值得预购的决策建议，帮助你在信息尚不完整的情况下做出明智的购买决定。',
        'preview',
        ARRAY['归唐', '发售日', '预购', '价格'],
        v_game_id_guitang,
        'free',
        'published',
        1450,
        7,
        NOW(),
        NOW()
    );
    v_count := v_count + 1;
    RAISE NOTICE '【文章2 插入完成】归唐发售日、价格、平台汇总 (字 1450)';

    -- 文章 3：黑神话钟馗开发进度
    INSERT INTO articles (title, content, excerpt, category, tags, game_id, required_tier, status, word_count, read_time, published_at, created_at)
    VALUES (
        '黑神话钟馗什么时候出？最新开发进度汇总',
        E'# 黑神话钟馗什么时候出？最新开发进度汇总\n\n**【国游爆料编辑部】深度分析**\n\n作为《黑神话：悟空》的续作，《黑神话：钟馗》自公布以来就备受全球玩家关注。本文将汇总目前已知的所有信息，分析开发进度，并对发售时间做出合理预测。\n\n## 目前已知信息汇总\n\n### 官方公布内容\n\n1. **公布时间**: 2024 年 8 月 20 日，随《黑神话：悟空》DLC 发售片尾彩蛋首次曝光\n2. **官方定名**: 《黑神话：钟馗》（Black Myth: Zhong Kui）\n3. **核心主题**: 围绕"生死"这一全人类共通的哲学命题展开\n4. **核心玩法**: 除了保留棍法外，将新增多种武器系统\n\n### 视觉与美术方向\n\n从已曝光的概念图和内部 Demo 片段来看：\n- 美术风格延续了悟空的写实东方神话路线\n- 钟馗形象融合了传统门神、判官、捉鬼天师的多重形象\n- 场景包含地府、阴阳交界、人间城镇等多元化环境\n- 画面精度预计将进一步提升\n\n### 技术团队规模\n\n根据公开招聘信息推测，游戏科学团队规模已扩展至 400+ 人，其中钟馗项目组可能占一半以上。\n\n## 招聘信息分析\n\n游戏科学招聘官网近期的岗位更新揭示了重要信号：\n\n### 关键岗位数量\n\n- **关卡设计师**: 8 人\n- **战斗设计师**: 5 人\n- **过场动画师**: 6 人\n- **技术美术**: 9 人\n- **引擎程序**: 4 人\n- **其他**: 引擎开发、QA、UI 等若干\n\n### 开发阶段判断\n\n从岗位构成分析：\n- **关卡设计师 × 8**: 暗示已进入关卡量产阶段，不是前期设计\n- **战斗设计师 × 5**: 战斗系统持续打磨和迭代中\n- **过场动画师 × 6**: 剧情演出推进中，说明剧本基本完成\n- **技术美术 × 9**: 数量最多，说明 UE5 工具链在持续优化，可能在进行多平台适配或画面升级\n\n**结论**：项目已脱离 Pre-Alpha 阶段，进入 Alpha 到 Beta 的过渡阶段。\n\n## 业内人士预测\n\n### 乐观预测 (2026 年底)\n\n- 依据：游戏科学已积累悟空的完整开发经验和工具链\n- 依据：团队规模大，并行开发效率高\n- 风险：时间过于紧迫，可能牺牲打磨时间\n\n### 中性预测 (2027 上半年)\n\n- 依据：从 2024 年 8 月公布算起，约 2.5-3 年开发周期\n- 依据：中型 3A 游戏标准开发周期 3-4 年\n- 可能性：这是最合理的预期\n\n### 保守预测 (2027 下半年 - 2028)\n\n- 依据：游戏科学一贯以"打磨到位才发售"著称，不急于抢档期\n- 依据：多武器系统和多场景对技术要求更高\n- 可能性：考虑到游戏科学的品质标准，这种可能性也不小\n\n## 合理发售时间推测\n\n综合分析，我们认为最可能的发售时间窗口是：\n\n**2027 年 Q3 (7-9 月)**\n\n### 推测理由\n\n1. **周期吻合**：从悟空 DLC 曝光算起，刚好 3 年\n2. **季节选择**：与悟空（夏季）类似，暑期档有利于销量\n3. **游戏科学风格**：不抢年底档期密集竞争，选择相对真空期\n4. **开发节奏**：按目前进度，2026 年底完成内容，2027 上半年测试和打磨，Q3 发售\n\n### 可能的发售窗口\n\n- **7 月下旬**: 暑期档开启，和悟空发售时间接近\n- **8 月中旬**: 避开其他大作竞争\n- **9 月上旬**: 国庆档前置\n\n## 风险与不确定性\n\n### 可能导致延期的因素\n\n1. **品质追求**：游戏科学可能在最后阶段因品质不达标而延期\n2. **多武器系统**：相比悟空的单武器，多武器系统增加了平衡性调试难度\n3. **多场景设计**：地府、阴阳交界等场景需要全新美术资源\n4. **技术挑战**：如遇引擎或硬件适配问题\n5. **市场判断**：游戏科学可能选择等待更有利的市场环境\n\n### 不会导致延期的因素\n\n1. **资金问题**：游戏科学现金流充足（悟空已产生丰厚回报）\n2. **团队流失**：目前团队稳定，未传出大规模离职消息\n3. **技术瓶颈**：已有 UE5 完整经验\n\n## 玩家能期待什么\n\n### 核心升级\n\n1. **多武器系统**: 刀、剑、枪、锤等至少 4 种武器\n2. **更丰富的变身**: 预计超过 72 种\n3. **更大的地图**: 多场景切换，非单一区域\n4. **更深度的剧情**: 钟馗捉鬼的故事线，可能更黑暗、更深刻\n\n### 延续的优点\n\n1. **顶级 BOSS 战设计**: 悟空的 BOSS 战已达到世界顶级水准\n2. **电影级过场演出**: 技术积累下的进一步升级\n3. **东方美学**: 延续的美术风格与文化内核\n4. **高完成度**: 一贯的品质标准\n\n## 总结\n\n《黑神话：钟馗》是最值得期待的国产游戏续作之一。根据目前的开发进度分析，**2027 年 Q3** 是最合理的发售窗口。当然，最终日期还是取决于游戏科学的品质标准。建议玩家耐心等待，游戏科学不会让我们失望。\n\n> 游戏科学官方目前未对本文推测做出任何回应。请关注官方渠道获取最新信息。\n\n*（全文完，预计阅读时间 9 分钟）*',
        '本文汇总了《黑神话：钟馗》的最新开发进度，通过分析游戏科学的招聘信息、团队规模和技术方向，结合业内专家预测，对游戏的发售时间做出了合理推断，并阐述了可能导致延期的风险因素和玩家可以期待的核心升级内容。',
        'analysis',
        ARRAY['黑神话钟馗', '游戏科学', '开发进度'],
        v_game_id_zhongkui,
        'free',
        'published',
        1580,
        9,
        NOW(),
        NOW()
    );
    v_count := v_count + 1;
    RAISE NOTICE '【文章3 插入完成】黑神话钟馗什么时候出？ (字 1580)';

