    INSERT INTO articles (title, content, excerpt, category, tags, game_id, required_tier, status, word_count, read_time, published_at, created_at)
    VALUES (
        '2026下半年国产3A游戏发售表：10款必关注的作品',
        E'# 2026下半年国产3A游戏发售表：10款必关注的作品\n\n**【国游爆料编辑部】精选整理**\n\n2026 年下半年将是国产 3A 游戏史上最密集的发售档期，多款备受期待的大作将陆续与玩家见面。本文按发售日期梳理了 10 款值得关注的作品。\n\n## 发售时间表\n\n### 八月 (已发售/即将发售)\n\n**1. 《山海旅人》** \n- **发售日**: 2026年8月 (已发售)\n- **开发商**: 小球工作室\n- **平台**: PC, Switch\n- **一句话点评**: 用像素艺术重现《山海经》的独立游戏佳作\n- **期待指数**: ⭐⭐⭐⭐\n\n**2. 《古剑四》** \n- **发售日**: 2026年8月 (CJ2026试玩)\n- **开发商**: 烛龙\n- **平台**: PC (预计)\n- **一句话点评**: UE5 技术加持下的国风 RPG，试玩反响两极但值得关注\n- **期待指数**: ⭐⭐⭐⭐⭐\n\n### 九月\n\n**3. 《百面千相》** \n- **发售日**: 2026年9月 (预估)\n- **开发商**: 叠纸游戏\n- **平台**: PC, 主机 (预计)\n- **一句话点评**: 面具变身机制的动作游戏，实机画面表现惊艳\n- **期待指数**: ⭐⭐⭐⭐\n\n### 十月 (重头戏)\n\n**4. 《归唐》** \n- **发售日**: 2026年10月18日 (推测)\n- **开发商**: 网易\n- **平台**: PC, PS5 (预计)\n- **一句话点评**: 敦煌美术风格的 UE5 旗舰大作，可能是年度最强国产\n- **期待指数**: ⭐⭐⭐⭐⭐\n\n**5. 《影之刃零》** \n- **发售日**: 2026年10月29日\n- **开发商**: 网易\n- **平台**: PC, PS5\n- **一句话点评**: 国产线性动作游戏新标杆，战斗系统获媒体一致好评\n- **期待指数**: ⭐⭐⭐⭐⭐\n\n**6. 《湮灭之潮》** \n- **发售日**: 2026年10月 (预估)\n- **开发商**: 腾讯天美\n- **平台**: PC, 主机 (预计)\n- **一句话点评**: 废土开放世界 RPG，腾讯首款国产 3A\n- **期待指数**: ⭐⭐⭐⭐\n\n### 十一月\n\n**7. 《剑影》** \n- **发售日**: 2026年11月 (预估)\n- **开发商**: 玄机科技\n- **平台**: PC (预计)\n- **一句话点评**: 武侠题材动作游戏，国风美术表现出色\n- **期待指数**: ⭐⭐⭐\n\n**8. 《无尽寒冬》** \n- **发售日**: 2026年11月 (预估)\n- **开发商**: 游族网络\n- **平台**: PC, 主机 (预计)\n- **一句话点评**: 末日生存题材，画面与玩法均有亮点\n- **期待指数**: ⭐⭐⭐\n\n### 十二月\n\n**9. 《江湖奇缘》** \n- **发售日**: 2026年12月 (预估)\n- **开发商**: 畅游\n- **平台**: PC (预计)\n- **一句话点评**: 金庸 IP 改编武侠 RPG，情怀与品质并重\n- **期待指数**: ⭐⭐⭐\n\n**10. 《封神演义》** \n- **发售日**: 2026年12月 (预估)\n- **开发商**: 完美世界\n- **平台**: PC, 主机 (预计)\n- **一句话点评**: 神话题材动作游戏，期待值高但信息较少\n- **期待指数**: ⭐⭐⭐\n\n## 最值得期待的 Top 3\n\n### 🏆 Top 1：《归唐》\n\n**入选理由**：\n- **品质信号最强**：SGF 全球首曝，数毛社、IGN、Kotaku 一致好评\n- **话题度最高**：敦煌美术风格在国际市场有差异化优势\n- **技术最前沿**：全套 UE5 技术栈（Lumen + Nanite + VSM）\n- **档期最关键**：10月18日，国庆后黄金档期\n\n**期待看点**：\n- 18 分钟实机演示中的攻城战能否完整呈现\n- 战斗系统的手感最终表现\n- 能否成为继黑神话悟空后又一爆款\n\n### 🏆 Top 2：《影之刃零》\n\n**入选理由**：\n- **完成度最高**：ChinaJoy 2026 提供了完整试玩，反馈极好\n- **品类最成熟**：线性动作游戏，风险可控\n- **媒体评价最好**：多家媒体评为"国产动作游戏新标杆"\n- **发售日最确定**：10月29日已官方公布\n\n**期待看点**：\n- 武器无缝切换系统的实际体验\n- BOSS 战设计的完整度\n- 能否达到战神级别的演出水准\n\n### 🏆 Top 3：《古剑四》\n\n**入选理由**：\n- **IP 情怀最深**：古剑系列积累了大量老玩家\n- **风格最独特**：幽冥国风美学，差异化强\n- **试玩最具争议**：两极分化的评价值得关注\n- **转型最彻底**：从传统 RPG 转向魂系动作，勇气可嘉\n\n**期待看点**：\n- UE5 画面的最终表现\n- 魂系战斗系统的平衡调整\n- 能否挽回因风格转变流失的老玩家\n\n## 购买建议\n\n### 预算充足型\n- 必买：《归唐》+《影之刃零》\n- 关注：《古剑四》《湮灭之潮》《百面千相》\n\n### 理性消费型\n- 等评测：先等《归唐》《影之刃零》发售看评测\n- 按需购买：根据评测分数和玩家反馈决定\n\n### 观望党\n- 关注首发周口碑\n- 等后续折扣（通常 1-3 个月）\n- 可以等年度打折包\n\n## 总结\n\n2026 年下半年是国产 3A 游戏的"黄金时代"，多款高品质大作集中发售。无论你是喜欢动作游戏、RPG 还是独立精品，都有值得期待的作品。希望这份发售表能帮你规划好购买节奏，不错过任何一款值得玩的佳作。\n\n> 本文发售日期基于多方信息整理，具体日期以各游戏官方公告为准。\n\n*（全文完，预计阅读时间 8 分钟）*',
        '本文梳理了2026年下半年即将发售的10款国产3A游戏，包括《归唐》《影之刃零》《古剑四》《百面千相》等备受期待的作品，按发售日期排序并给出了每款游戏的一句话点评，同时评选出最值得期待的Top 3，并提供了不同预算玩家的购买建议。',
        'preview',
        ARRAY['国产3A', '发售日历', '2026'],
        NULL,
        'free',
        'published',
        1480,
        8,
        NOW(),
        NOW()
    );
    v_count := v_count + 1;
    RAISE NOTICE '【文章4 插入完成】2026下半年国产3A游戏发售表 (字 1480)';

    -- 文章 5：百面千相实机画面分析
    INSERT INTO articles (title, content, excerpt, category, tags, game_id, required_tier, status, word_count, read_time, published_at, created_at)
    VALUES (
        '百面千相实机画面分析：叠纸的3A之路走到哪了？',
        E'# 百面千相实机画面分析：叠纸的3A之路走到哪了？\n\n**【国游爆料编辑部】画面解析**\n\n《百面千相》是叠纸游戏进军 3A 领域的首部作品，以独特的"面具变身"机制备受期待。本文将分析已公开的实机画面，探讨叠纸的 3A 开发能力。\n\n## 已公开实机画面回顾\n\n### 2024 年首曝画面\n\n- **公开时间**: 2024 年 8 月\n- **画面内容**: 主角在古村落中奔跑、与面具交互\n- **技术特点**: 虚幻 5 引擎，画面表现中等偏上\n- **玩家反应**: 关注"面具变身"机制，对画面有褒有贬\n\n### 2025 年更新画面\n\n- **公开时间**: 2025 年 3 月\n- **画面内容**: 战斗系统演示，面具切换特效\n- **技术特点**: 战斗系统展示，动作流畅度提升\n- **玩家反应**: 对战斗手感有期待，部分玩家认为偏轻量化\n\n### 2026 年最新画面\n\n- **公开时间**: 2026 年 7 月 (社交媒体流传)\n- **画面内容**: 7 张实机截图，疑似内部测试版本\n- **技术特点**: UI 大幅调整，疑似战斗系统改版\n- **玩家反应**: 讨论热烈，出现两极分化\n\n## 画面技术分析\n\n### 优点\n\n1. **光影系统成熟**\n   - 场景光照自然，氛围营造到位\n   - 人物面部光影处理细腻\n   - 环境光遮蔽和全局光照效果明显\n\n2. **材质表现出色**\n   - 衣物布料的纹理和褶皱还原度高\n   - 金属、玉石等不同材质的质感区分明显\n   - 面具的材质和光泽表现突出\n\n3. **特效系统丰富**\n   - 面具切换时的粒子特效设计精美\n   - 技能释放的光效和震屏反馈有冲击力\n   - 环境中的自然粒子（飘落的花瓣、水面波纹）增加沉浸感\n\n4. **美术风格统一**\n   - 整体美术风格延续了叠纸在《闪耀暖暖》《无限暖暖》中的精细路线\n   - 古风与玄幻的结合做得很自然\n   - 色彩搭配和谐，具有辨识度\n\n### 有待提升\n\n1. **多边形密度**\n   - 部分远景场景的细节密度仍有不足\n   - 与《黑神话：悟空》《归唐》等顶级 3A 相比，有一定差距\n\n2. **动画表现**\n   - 主角奔跑、攻击的动画流畅度有待提升\n   - 部分敌人 AI 动作略显僵硬\n\n3. **场景规模**\n   - 目前公开的场景多为中小规模\n   - 尚未看到大规模开放世界的展示\n\n4. **物理系统**\n   - 环境交互的物理反馈偏少\n   - 破坏物理、布料物理的表现有限\n\n## 与同类型游戏对比\n\n### 对比《黑神话：悟空》\n\n| 维度 | 百面千相 | 黑神话：悟空 |\n|------|---------|------------|\n| 美术风格 | 古风玄幻、色彩鲜明 | 写实东方、光影厚重 |\n| 画面精度 | 中等偏上 | 顶级水准 |\n| 场景规模 | 未公开 (推测中等) | 线性关卡但密度极高 |\n| 动作流畅度 | 有提升空间 | 业界顶级 |\n| 特色机制 | 面具变身 (切换) | 72变 (形态转换) |\n\n**分析**：百面千相的画面精度目前难以达到黑神话悟空的水准，但在美术风格上有自己的特色。叠纸擅长的精细路线与游戏科学的写实路线形成互补。\n\n### 对比《鸣潮》\n\n| 维度 | 百面千相 | 鸣潮 |\n|------|---------|------|\n| 平台 | PC/主机 (预计) | PC/移动端 |\n| 开放度 | 未知 (推测半开放) | 全开放世界 |\n| 战斗系统 | 面具切换机制 | 高速连携技系统 |\n| 受众 | 更偏向 PC/主机玩家 | 全平台玩家 |\n\n**分析**：百面千相如果能在 PC/主机平台提供更好的战斗体验，将形成与鸣潮的差异化竞争。\n\n### 对比传统国产 RPG\n\n相比《古剑》《仙剑》等传统国产 RPG，百面千相在战斗系统和画面表现力上有显著提升，代表了叠纸从休闲/中度游戏向 3A 动作游戏的转型成果。\n\n## 开发进度评估\n\n### 目前进度\n\n1. **核心系统**: 面具切换、战斗框架已基本成型\n2. **美术资源**: 主角、面具、核心场景美术完成度较高\n3. **优化阶段**: 从最新截图的 UI 变化来看，可能在进行深度优化和改版\n\n### 预计发售时间\n\n- **乐观**: 2026 年 9-10 月\n- **中性**: 2026 年 12 月 - 2027 年 1 月\n- **保守**: 2027 年 Q1\n\n### 可能延期的因素\n\n1. 战斗系统改版带来的额外开发量\n2. 大规模开放世界的内容填充\n3. 多平台适配的技术挑战\n4. 品质打磨的时间投入\n\n## 结论\n\n《百面千相》展示了叠纸游戏在 3A 领域的决心和初步成果。画面表现中上水平，美术风格有辨识度，面具变身机制有创意。但与顶级 3A 相比，在画面精度、场景规模和动作流畅度上仍有提升空间。\n\n叠纸的 3A 之路才刚刚开始，百面千相的表现将决定这家以女性向游戏闻名的公司能否在硬核玩家市场站稳脚跟。无论结果如何，敢试敢闯的勇气值得肯定。\n\n**建议**：关注后续官方公布的更多实机演示，特别是大规模场景和多面具联动的战斗表现。\n\n*（全文完，预计阅读时间 9 分钟）*',
        '本文分析了叠纸游戏3A新作《百面千相》的已公开实机画面，从光影、材质、特效等维度进行技术解析，并与《黑神话：悟空》《鸣潮》等同类型游戏进行对比，评估了开发进度和可能的发售时间，探讨了叠纸从休闲游戏转向3A领域的挑战与机遇。',
        'analysis',
        ARRAY['百面千相', '叠纸', '实机', '3A'],
        v_game_id_baimian,
        'free',
        'published',
        1520,
        9,
        NOW(),
        NOW()
    );
    v_count := v_count + 1;
    RAISE NOTICE '【文章5 插入完成】百面千相实机画面分析 (字 1520)';

    RAISE NOTICE '─────────────────────────────────────';
